import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CeYlivdO.js";const v=JSON.parse('{"title":"Move semantics and rvalue references","description":"Understand the value category system, master move construction, RVO, and perfect forwarding.","frontmatter":{"title":"Move semantics and rvalue references","description":"Understand the value category system, master move construction, RVO, and perfect forwarding."},"headers":[],"relativePath":"en/vol2-modern-features/ch00-move-semantics/index.md","filePath":"en/vol2-modern-features/ch00-move-semantics/index.md","lastUpdated":null}'),o={name:"en/vol2-modern-features/ch00-move-semantics/index.md"};function s(i,e,c,m,l,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="move-semantics-and-rvalue-references" tabindex="-1">Move Semantics and Rvalue References <a class="header-anchor" href="#move-semantics-and-rvalue-references" aria-label="Permalink to &quot;Move Semantics and Rvalue References&quot;">​</a></h1><p>Move semantics is one of the most important features in C++11—it makes &quot;transferring resource ownership&quot; a first-class citizen, fundamentally changing how we handle copy overhead. In this chapter, we start from the value category system to understand what lvalues and rvalues are and why we need rvalue references. We then dive into the implementation principles of move constructors and move assignments, see how much the compiler&#39;s RVO optimization saves you, and finally tie everything together with perfect forwarding. Move semantics is not just a performance optimization; it is the cornerstone of understanding modern C++ resource management.</p><h2 id="chapter-contents" tabindex="-1">Chapter Contents <a class="header-anchor" href="#chapter-contents" aria-label="Permalink to &quot;Chapter Contents&quot;">​</a></h2><ul><li><a href="./01-rvalue-reference">Rvalue References: From Copy to Move</a></li><li><a href="./02-move-semantics">Move Construction and Move Assignment</a></li><li><a href="./03-rvo-nrvo">RVO and NRVO: Compiler Return Value Optimization</a></li><li><a href="./04-perfect-forwarding">Perfect Forwarding: Preserving Value Categories in Argument Passing</a></li><li><a href="./05-move-in-practice">Move Semantics in Practice: From STL to Custom Types</a></li></ul>',4)])])}const f=a(o,[["render",s]]);export{v as __pageData,f as default};
